public static FrameProcessorChain create(Context context, float pixelWidthHeightRatio, int inputWidth, int inputHeight, List<GlEffect> effects, boolean enableExperimentalHdrEditing) throws TransformationException {
  checkArgument(inputWidth > 0, "inputWidth must be positive");
  checkArgument(inputHeight > 0, "inputHeight must be positive");
  ExecutorService singleThreadExecutorService = Util.newSingleThreadExecutor(THREAD_NAME);
  try {
    return singleThreadExecutorService.submit(() -> createOpenGlObjectsAndFrameProcessorChain(context, pixelWidthHeightRatio, inputWidth, inputHeight, effects, enableExperimentalHdrEditing, singleThreadExecutorService)).get();
  } catch (ExecutionException e) {
    throw TransformationException.createForFrameProcessorChain(e, TransformationException.ERROR_CODE_GL_INIT_FAILED);
  } catch (InterruptedException e) {
    Thread.currentThread().interrupt();
    throw TransformationException.createForFrameProcessorChain(e, TransformationException.ERROR_CODE_GL_INIT_FAILED);
  } catch (CancellationException e) {
    throw TransformationException.createForFrameProcessorChain(e, TransformationException.ERROR_CODE_GL_INIT_FAILED);
  } catch (RejectedExecutionException e) {
    throw TransformationException.createForFrameProcessorChain(e, TransformationException.ERROR_CODE_GL_INIT_FAILED);
  } catch (GlException e) {
    throw TransformationException.createForFrameProcessorChain(e, TransformationException.ERROR_CODE_GL_INIT_FAILED);
  }
}
